export const REPORT_OG_PATH = '/report-og.webp'
export const REPORT_OG_URL = 'https://krta.cc/report-og.webp'
export const REPORT_OG_CONTENT_TYPE = 'image/webp'
export const REPORT_OG_WIDTH = 256
export const REPORT_OG_HEIGHT = 256
export const REPORT_OG_ALT = 'Karuta report form.'

const REPORT_OG_BASE64 = ""

function decodeBase64(value: string): Uint8Array {
  const binary = atob(value)
  const bytes = new Uint8Array(binary.length)
  for (let i = 0; i < binary.length; i += 1) {
    bytes[i] = binary.charCodeAt(i)
  }
  return bytes
}

export const REPORT_OG_BYTES = decodeBase64(REPORT_OG_BASE64)
